import React, { useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { ArrowDown, ArrowRight, ArrowUpRight, Bell, Bookmark, Check, CheckCheck, ChevronDown, CircleHelp, Clock3, Compass, FilePlus2, Filter, FlaskConical, FolderKanban, GraduationCap, Lightbulb, LockKeyhole, LogOut, Menu, MessageCircle, Plus, RefreshCw, Search, Send, ShieldCheck, Sparkles, TrendingUp, Users, X } from 'lucide-react';
import './styles.css';

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:5000';
const categories = ['All ideas', 'Technology', 'Healthcare', 'Sustainability', 'Education', 'Community'];
const initials = (name = 'Student') => name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase();

async function request(path, options = {}, token = '') {
  const response = await fetch(`${API_URL}${path}`, {
    ...options,
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}), ...options.headers },
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(payload.message || 'Something went wrong. Please try again.');
  return payload;
}

function App() {
  const [session, setSession] = useState(() => { try { return JSON.parse(localStorage.getItem('innobridge-session') || 'null'); } catch { return null; } });
  const [view, setView] = useState(session?.role === 'mentor' ? 'mentor-home' : session ? 'home' : 'welcome');
  const [authMode, setAuthMode] = useState('login');
  const [ideas, setIdeas] = useState([]);
  const [myIdeas, setMyIdeas] = useState([]);
  const [teams, setTeams] = useState([]);
  const [memberships, setMemberships] = useState([]);
  const [progress, setProgress] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [mentors, setMentors] = useState([]);
  const [guidanceRequests, setGuidanceRequests] = useState([]);
  const [students, setStudents] = useState([]);
  const [feedback, setFeedback] = useState([]);
  const [recommendations, setRecommendations] = useState({ students: [], mentors: [] });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [toast, setToast] = useState('');
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('All ideas');
  const [modal, setModal] = useState(false);
  const [mobileNav, setMobileNav] = useState(false);

  const loadIdeas = async () => {
    setLoading(true); setError('');
    try { const data = await request('/api/ideas'); setIdeas(Array.isArray(data) ? data : []); }
    catch (err) { setError(err.message.includes('Failed to fetch') ? 'Can’t reach the InnoBridge server. Start the backend or check your API URL.' : err.message); }
    finally { setLoading(false); }
  };
  const loadWorkspace = async () => {
    if (!session?.token) return;
    const mentor = session.role === 'mentor';
    const jobs = mentor ? [
      ['/api/mentor/guidance-requests', setGuidanceRequests], ['/api/teams', setTeams], ['/api/team-members', setMemberships], ['/api/feedback', setFeedback], ['/api/notifications', setNotifications], ['/api/students', setStudents],
    ] : [
      ['/api/student/ideas', setMyIdeas], ['/api/student/teams', setTeams], ['/api/team-members', setMemberships], ['/api/progress', setProgress], ['/api/notifications', setNotifications], ['/api/mentors', setMentors], ['/api/student/guidance-requests', setGuidanceRequests], ['/api/student/feedback', setFeedback], ['/api/students', setStudents],
    ];
    const results = await Promise.allSettled(jobs.map(([path]) => request(path, {}, session.token)));
    results.forEach((result, index) => { if (result.status === 'fulfilled' && Array.isArray(result.value)) jobs[index][1](result.value); });
  };
  const loadRecommendations = async () => {
    if (!session?.token || session.role !== 'student') return;
    const [studentRecs, mentorRecs] = await Promise.allSettled([
      request(`/api/recommendations/students/${session.studentId}`, {}, session.token),
      request(`/api/recommendations/mentors/${session.studentId}`, {}, session.token),
    ]);
    setRecommendations({ students: studentRecs.status === 'fulfilled' ? studentRecs.value : [], mentors: mentorRecs.status === 'fulfilled' ? mentorRecs.value : [] });
  };
  useEffect(() => { if (session) { loadIdeas(); loadWorkspace(); } }, [session]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 3200); return () => clearTimeout(timer); }, [toast]);

  const filteredIdeas = useMemo(() => ideas.filter((idea) => {
    const skills = Array.isArray(idea.requiredSkills) ? idea.requiredSkills.join(' ') : idea.requiredSkills || '';
    const text = `${idea.title || ''} ${idea.description || ''} ${idea.category || ''} ${skills}`.toLowerCase();
    return text.includes(query.toLowerCase()) && (category === 'All ideas' || (idea.category || '').toLowerCase() === category.toLowerCase());
  }), [ideas, query, category]);
  const logout = () => { localStorage.removeItem('innobridge-session'); setSession(null); setView('welcome'); setIdeas([]); setMyIdeas([]); setTeams([]); setMemberships([]); setProgress([]); setNotifications([]); setMentors([]); setGuidanceRequests([]); setStudents([]); setFeedback([]); setRecommendations({students:[],mentors:[]}); };
  const notify = (message) => setToast(message);
  const showAuth = (mode = 'login') => { setAuthMode(mode); setView('auth'); };
  const go = (next) => { setView(next); setMobileNav(false); };
  const unreadCount = notifications.filter((item) => !item.is_read).length;
  if (view === 'welcome') return <Welcome onStart={() => showAuth('register')} onLogin={() => showAuth('login')} />;
  if (view === 'auth') return <Auth mode={authMode} setMode={setAuthMode} onBack={() => setView('welcome')} onSuccess={(data, name, role) => {
    const next = { token: data.token, role, studentId: data.student_id, mentorId: data.mentor_id, name: name || (role === 'mentor' ? 'Mentor' : 'Student') };
    localStorage.setItem('innobridge-session', JSON.stringify(next)); setSession(next); setView(role === 'mentor' ? 'mentor-home' : 'home');
  }} />;
  const mentor = session?.role === 'mentor';
  const currentLabel = ({ home:'Discover', 'my-ideas':'My ideas', teams:'My teams', mentors:'Mentorship', connections:'Connections', notifications:'Notifications', 'mentor-home':'Requests', 'mentor-teams':'Projects' })[view] || 'Workspace';
  return <div className="app-shell"><Sidebar current={view} role={session?.role} go={go} logout={logout} unreadCount={unreadCount} mobileNav={mobileNav} setMobileNav={setMobileNav} />
    <main className="main-area"><header className="topbar"><button className="icon-btn mobile-menu" onClick={() => setMobileNav(true)} aria-label="Open menu"><Menu size={19} /></button><div className="crumb">Workspace <span>/</span> <strong>{currentLabel}</strong></div><div className="top-actions"><button className="icon-btn notification-button" onClick={() => go('notifications')} aria-label="Notifications"><Bell size={18} />{unreadCount > 0 && <i />}</button><div className="user-chip"><span className="avatar">{initials(session?.name)}</span><span>{session?.name || 'Student'}</span><ChevronDown size={14} /></div></div></header>
      {view === 'home' && !mentor && <Discover ideas={filteredIdeas} total={ideas.length} loading={loading} error={error} query={query} setQuery={setQuery} category={category} setCategory={setCategory} onCreate={() => setModal(true)} onRefresh={loadIdeas} />}
      {view === 'my-ideas' && !mentor && <MyIdeas ideas={myIdeas} token={session?.token} loading={loading} onCreate={() => setModal(true)} onRefresh={() => { loadIdeas(); loadWorkspace(); }} notify={notify} />}
      {view === 'teams' && !mentor && <Teams teams={teams} ideas={myIdeas} progress={progress} feedback={feedback} memberships={memberships} loading={loading} token={session?.token} studentId={session?.studentId} students={students} onRefresh={() => { loadWorkspace(); loadIdeas(); }} notify={notify} />}
      {view === 'mentors' && !mentor && <Mentors mentors={mentors} ideas={myIdeas} requests={guidanceRequests} token={session?.token} notify={notify} onRefresh={loadWorkspace} />}
      {view === 'connections' && !mentor && <Connections recommendations={recommendations} students={students} teams={teams} myIdeas={myIdeas} token={session?.token} studentId={session?.studentId} onLoad={loadRecommendations} notify={notify} />}
      {view === 'notifications' && <Notifications notifications={notifications} token={session?.token} onRefresh={loadWorkspace} onBack={() => go(mentor ? 'mentor-home' : 'home')} />}
      {view === 'mentor-home' && mentor && <MentorDashboard requests={guidanceRequests} ideas={ideas} students={students} token={session?.token} onRefresh={loadWorkspace} notify={notify} />}
      {view === 'mentor-teams' && mentor && <MentorProjects teams={teams} feedback={feedback} memberships={memberships} students={students} ideas={ideas} token={session?.token} notify={notify} onRefresh={loadWorkspace} />}
    </main>
    {modal && <IdeaModal token={session?.token} onClose={() => setModal(false)} onCreated={() => { setModal(false); loadIdeas(); loadWorkspace(); notify('Your idea is now on InnoBridge.'); }} />}
    {toast && <div className="toast"><Check size={16} />{toast}</div>}
  </div>;
}

function Brand({ inverse = false }) { return <div className={`brand ${inverse ? 'brand-inverse' : ''}`}><span className="brand-mark"><span /><span /><span /></span><span>innobridge</span></div>; }
function Welcome({ onStart, onLogin }) {
  return <div className="welcome-page"><nav className="welcome-nav"><Brand /><div className="nav-right"><a href="#how">How it works</a><a href="#principles">Our promise</a><button className="text-button" onClick={onLogin}>Log in <ArrowUpRight size={15} /></button></div></nav>
    <section className="hero"><div className="hero-copy"><div className="eyebrow"><span className="live-dot" /> A home for student innovation</div><h1>Big ideas deserve <em>good company.</em></h1><p>Find your people, get thoughtful guidance, and build something that makes a difference.</p><div className="hero-actions"><button className="button button-dark" onClick={onStart}>Find your bridge <ArrowRight size={17} /></button><a className="quiet-link" href="#how">Explore the platform <ArrowDown size={15} /></a></div><div className="hero-foot"><div className="avatar-stack"><span>AK</span><span>RM</span><span>PS</span><span>+</span></div><span>Made for curious minds<br /><b>ready to build together</b></span></div></div>
      <div className="hero-art" aria-label="Illustration of ideas connecting people"><div className="art-grid" /><div className="orbit orbit-one" /><div className="orbit orbit-two" /><div className="art-core"><span className="core-spark">✳</span><span>one idea<br />can go further</span></div><div className="float-note note-one"><span className="note-icon note-lime"><Lightbulb size={18} /></span><span><b>Start with an idea</b><small>Share what you’re imagining</small></span></div><div className="float-note note-two"><span className="note-icon note-peach"><Users size={18} /></span><span><b>Find your people</b><small>Build a team that fits</small></span></div><div className="float-tag">Ideas · People · Possibility</div></div>
    </section><div className="trust-strip"><span>THE BRIDGE BETWEEN</span><b>Curiosity <i>×</i> Collaboration <i>×</i> Impact</b><span className="strip-right">BUILT FOR STUDENTS, BY STUDENTS</span></div>
    <section id="how" className="how-section"><div className="section-intro"><div className="eyebrow">A better place to begin</div><h2>From “what if?”<br /><em>to “we did it.”</em></h2><p>One thoughtful space to turn a spark into a real project, with the right support at every step.</p></div><div className="steps"><article><span className="step-no">01</span><div className="step-icon"><Lightbulb size={21} /></div><h3>Put your idea out there</h3><p>Describe the problem you care about and what you hope to change.</p></article><article><span className="step-no">02</span><div className="step-icon"><Users size={21} /></div><h3>Meet the right people</h3><p>Find collaborators whose skills and interests bring your idea to life.</p></article><article><span className="step-no">03</span><div className="step-icon"><GraduationCap size={21} /></div><h3>Grow with a mentor</h3><p>Get practical guidance from people who have been there before.</p></article></div></section>
    <section id="principles" className="promise"><div className="promise-icon"><ShieldCheck size={24} /></div><div><span className="eyebrow">Built on trust</span><h2>Your idea stays <em>yours.</em></h2><p>Choose what you share. InnoBridge is designed to help you find support without giving up ownership of your work.</p></div><button className="round-arrow" onClick={onStart} aria-label="Get started"><ArrowRight size={20} /></button></section>
    <footer className="welcome-footer"><Brand /><span>Make room for what could be.</span><button className="text-button" onClick={onStart}>Create your account <ArrowRight size={15} /></button></footer>
  </div>;
}

function Auth({ mode, setMode, onBack, onSuccess }) {
  const [accountType, setAccountType] = useState('student');
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const [form, setForm] = useState({ first_name:'', last_name:'', email:'', password:'', department:'', year:'', skills:'', phone:'', expertise:'', organization:'', designation:'', experience:'', bio:'' });
  const update = (event) => setForm({ ...form, [event.target.name]: event.target.value });
  const submit = async (event) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const rolePath = accountType === 'mentor' ? '/api/mentor-login' : '/api/login';
      if (mode === 'register') {
        if (accountType === 'mentor') await request('/api/mentors', { method:'POST', body:JSON.stringify(form) });
        else await request('/api/students', { method:'POST', body:JSON.stringify({ ...form, skills:form.skills.split(',').map((s) => s.trim()).filter(Boolean), year:form.year ? Number(form.year) : undefined }) });
      }
      const data = await request(rolePath, { method:'POST', body:JSON.stringify({ email:form.email, password:form.password }) });
      onSuccess(data, `${form.first_name} ${form.last_name}`.trim() || form.email.split('@')[0], accountType);
    } catch (err) { setError(err.message.includes('Failed to fetch') ? 'The server is offline. Start the backend and try again.' : err.message); }
    finally { setBusy(false); }
  };
  return <div className="auth-page"><button className="back-link" onClick={onBack}>← <span>Back to InnoBridge</span></button><div className="auth-shell"><div className="auth-aside"><Brand inverse /><div><span className="eyebrow">Your next chapter starts here</span><h1>Make room for what <em>could be.</em></h1><p>Good ideas grow when the right people find each other.</p></div><div className="auth-aside-bottom"><ShieldCheck size={16} /> Your work. Your choices. Your future.</div></div><div className="auth-form-side"><div className="auth-heading"><div className="eyebrow">INNOBRIDGE COMMUNITY</div><h2>{mode === 'login' ? 'Welcome back' : 'Create your account'}</h2><p>{mode === 'login' ? 'Pick up where your ideas left off.' : 'Choose how you’ll take part in the community.'}</p></div><div className="role-switch"><button type="button" className={accountType === 'student' ? 'selected' : ''} onClick={() => setAccountType('student')}><GraduationCap size={15} /> Student</button><button type="button" className={accountType === 'mentor' ? 'selected' : ''} onClick={() => setAccountType('mentor')}><Users size={15} /> Mentor</button></div>
    <form onSubmit={submit} className="auth-form">{mode === 'register' && <><div className="field-row"><Field label="First name" name="first_name" value={form.first_name} onChange={update} required placeholder="Aarav" /><Field label="Last name" name="last_name" value={form.last_name} onChange={update} required placeholder="Sharma" /></div>{accountType === 'mentor' ? <><div className="field-row"><Field label="Expertise" name="expertise" value={form.expertise} onChange={update} required placeholder="Product design" /><Field label="Organization" name="organization" value={form.organization} onChange={update} placeholder="Company or institution" /></div><div className="field-row"><Field label="Designation" name="designation" value={form.designation} onChange={update} placeholder="Senior researcher" /><Field label="Years of experience" name="experience" value={form.experience} onChange={update} type="number" min="0" placeholder="8" /></div><label className="field"><span>Short bio</span><textarea name="bio" value={form.bio} onChange={update} rows="2" placeholder="A few words about the work you do" /></label></> : <><div className="field-row"><Field label="Department" name="department" value={form.department} onChange={update} placeholder="Computer Science" /><Field label="Year of study" name="year" value={form.year} onChange={update} type="number" min="1" max="8" placeholder="2" /></div><Field label="Skills you bring" name="skills" value={form.skills} onChange={update} placeholder="Design, Python, research…" hint="Separate skills with commas" /></>}</>}
      <Field label="Email address" type="email" name="email" value={form.email} onChange={update} required placeholder="you@university.edu" /><Field label="Password" type="password" name="password" value={form.password} onChange={update} required minLength="6" placeholder="At least 6 characters" />{error && <div className="form-error" role="alert">{error}</div>}<button className="button button-dark full-button" disabled={busy}>{busy ? 'One moment…' : mode === 'login' ? `Log in as ${accountType}` : `Create ${accountType} account`} <ArrowRight size={16} /></button></form><div className="auth-switch">{mode === 'login' ? 'New to InnoBridge?' : 'Already part of the community?'} <button onClick={() => { setMode(mode === 'login' ? 'register' : 'login'); setError(''); }}>{mode === 'login' ? 'Create an account' : 'Log in'}</button></div><div className="privacy-note"><LockKeyhole size={14} /> Your account details are kept private and secure.</div></div></div></div>;
}
function Field({ label, hint, ...props }) { return <label className="field"><span>{label}</span><input {...props} />{hint && <small>{hint}</small>}</label>; }

function Sidebar({ current, role, go, logout, unreadCount, mobileNav, setMobileNav }) {
  const nav = role === 'mentor' ? [{ id:'mentor-home', label:'Guidance requests', icon:MessageCircle }, { id:'mentor-teams', label:'Project feedback', icon:FolderKanban }, { id:'notifications', label:'Notifications', icon:Bell }] : [{ id:'home', label:'Discover', icon:Compass }, { id:'my-ideas', label:'My ideas', icon:Lightbulb }, { id:'teams', label:'My teams', icon:FolderKanban }, { id:'mentors', label:'Mentorship', icon:GraduationCap }, { id:'connections', label:'Connections', icon:Users }, { id:'notifications', label:'Notifications', icon:Bell }];
  return <><aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}><div className="sidebar-top"><Brand /><button className="icon-btn close-nav" onClick={() => setMobileNav(false)} aria-label="Close menu"><X size={18} /></button></div><div className="workspace-switch"><span className="workspace-avatar">{role === 'mentor' ? 'ME' : 'IB'}</span><span><b>{role === 'mentor' ? 'Mentor workspace' : 'Student workspace'}</b><small>InnoBridge community</small></span><ChevronDown size={15} /></div><div className="nav-label">WORKSPACE</div><nav>{nav.map(({ id, label, icon: Icon }) => <button key={id} className={`side-link ${current === id ? 'active' : ''}`} onClick={() => go(id)}><Icon size={18} strokeWidth={1.8} /><span>{label}</span>{id === 'notifications' && unreadCount > 0 && <span className="nav-count">{unreadCount > 9 ? '9+' : unreadCount}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="help-card"><div className="help-head"><CircleHelp size={17} /><span>Need a hand?</span></div><p>We’re here to help your idea find its footing.</p><button onClick={() => go(role === 'mentor' ? 'mentor-home' : 'mentors')}>{role === 'mentor' ? 'Review requests' : 'Explore mentorship'} <ArrowRight size={13} /></button></div><div className="sidebar-user"><span className="avatar">ST</span><span><b>Your workspace</b><small>{role === 'mentor' ? 'Mentor account' : 'Student account'}</small></span><button className="icon-btn logout-btn" onClick={logout} title="Log out"><LogOut size={16} /></button></div></div></aside>{mobileNav && <button className="nav-scrim" onClick={() => setMobileNav(false)} aria-label="Close navigation" />}</>;
}
function Discover({ ideas, total, loading, error, query, setQuery, category, setCategory, onCreate, onRefresh }) {
  return <div className="content-wrap"><div className="welcome-banner"><div><div className="eyebrow"><span className="live-dot" /> YOUR NEXT COLLABORATION STARTS HERE</div><h1>Ideas move further <em>together.</em></h1><p>Find a spark worth building on, or put your own idea out into the world.</p><button className="button button-dark" onClick={onCreate}><Plus size={17} /> Share an idea</button></div><div className="banner-art"><div className="banner-orbit" /><div className="banner-sun">✳</div><span className="banner-leaf leaf-a" /><span className="banner-leaf leaf-b" /><span className="banner-caption">A place for<br /><b>possibility</b></span></div></div>
    <div className="metric-row"><Metric icon={Lightbulb} label="Ideas shared" value={total} /><Metric icon={Users} label="Ways to contribute" value="Open" tone="peach" /><Metric icon={GraduationCap} label="Mentors to meet" value="Growing" tone="lavender" /><div className="metric-note"><span className="metric-note-icon"><Sparkles size={17} /></span><p><b>Small step, big possibility.</b><br />Every great project starts with a conversation.</p></div></div>
    <div className="section-heading ideas-heading"><div><div className="eyebrow">COMMUNITY IDEAS</div><h2>Find something <em>to build on.</em></h2><p>Browse what students are working on and find where you can help.</p></div><button className="button button-outline" onClick={onCreate}>Post an idea <Plus size={15} /></button></div>
    <div className="filter-bar"><div className="search-box"><Search size={17} /><input aria-label="Search ideas" placeholder="Search ideas, skills, or topics" value={query} onChange={(e) => setQuery(e.target.value)} />{query && <button className="clear-search" onClick={() => setQuery('')}><X size={14} /></button>}</div><div className="filter-wrap"><Filter size={16} /><select value={category} onChange={(e) => setCategory(e.target.value)} aria-label="Filter by category">{categories.map((item) => <option key={item}>{item}</option>)}</select><ChevronDown size={14} /></div><span className="result-count">{ideas.length} {ideas.length === 1 ? 'idea' : 'ideas'}</span></div>
    {error && <div className="error-banner"><span>{error}</span><button onClick={onRefresh}>Try again</button></div>}
    {loading ? <div className="loading-state"><span className="spinner" /> Gathering ideas…</div> : ideas.length ? <div className="idea-grid">{ideas.map((idea, index) => <IdeaCard key={idea._id || idea.idea_id || index} idea={idea} index={index} />)}</div> : <div className="empty-state"><div className="empty-art"><FlaskConical size={24} /><span>✳</span></div><div className="eyebrow">A FRESH PAGE</div><h3>{query || category !== 'All ideas' ? 'No ideas found just yet.' : 'Be the first to share an idea.'}</h3><p>{query || category !== 'All ideas' ? 'Try a different search or category to see what’s growing.' : 'The next great project could start with you. Share what you’re thinking and invite the community in.'}</p><button className="button button-dark" onClick={onCreate}>Share the first idea <ArrowRight size={16} /></button></div>}
    <div className="footnote"><ShieldCheck size={15} /><span>Students choose how their ideas are shared. Public posts are visible to the community.</span><button>How privacy works <ArrowUpRight size={13} /></button></div>
  </div>;
}
function Metric({ icon: Icon, label, value, tone = '' }) { return <div className="metric"><span className={`metric-icon ${tone}`}><Icon size={18} /></span><span className="metric-copy"><small>{label}</small><b>{value}</b></span><ArrowUpRight className="metric-arrow" size={15} /></div>; }
const tones = ['mint', 'peach', 'blue', 'lavender'];
function IdeaCard({ idea, index }) {
  const [saved, setSaved] = useState(false); const skills = Array.isArray(idea.requiredSkills) ? idea.requiredSkills : (idea.requiredSkills || '').split(',').map(s => s.trim()).filter(Boolean);
  const stack = Array.isArray(idea.technologyStack) ? idea.technologyStack : (idea.technologyStack || '').split(',').map(s => s.trim()).filter(Boolean);
  return <article className="idea-card"><div className={`card-top ${tones[index % tones.length]}`}><div className="card-topline"><span className="category-pill">{idea.category || 'Open idea'}</span><button className={`save-btn ${saved ? 'saved' : ''}`} onClick={() => setSaved(!saved)} aria-label={saved ? 'Remove bookmark' : 'Save idea'}><Bookmark size={16} fill={saved ? 'currentColor' : 'none'} /></button></div><div className="card-symbol">{index % 3 === 0 ? <Lightbulb /> : index % 3 === 1 ? <Compass /> : <Sparkles />}</div><span className="card-id">IDEA / {String(idea.idea_id || index + 1).padStart(3, '0')}</span></div><div className="card-body"><h3>{idea.title}</h3><p>{idea.description || idea.problemStatement || 'An early stage idea looking for thoughtful collaborators.'}</p>{idea.expectedOutcome && <div className="outcome"><span>HOPING TO</span>{idea.expectedOutcome}</div>}<div className="tag-row">{[...skills, ...stack].slice(0, 4).map((skill) => <span key={skill}>{skill}</span>)}</div><div className="card-footer"><div className="mini-owner"><span className="avatar small-avatar">{initials(idea.ownerName || 'IB')}</span><span><small>Shared by</small><b>{idea.ownerName || 'InnoBridge student'}</b></span></div><button className="card-open" aria-label={`View ${idea.title}`}><ArrowUpRight size={17} /></button></div></div></article>;
}
function MyIdeas({ ideas, token, loading, onCreate, onRefresh, notify }) {
  const [updating, setUpdating] = useState(''); const [error, setError] = useState('');
  const setVisibility = async (idea) => { const next = (idea.visibility || 'public').toLowerCase() === 'public' ? 'private' : 'public'; setUpdating(idea._id); setError(''); try { await request('/api/privacy-settings', {method:'POST', body:JSON.stringify({idea_id:idea._id, visibility:next})}, token); await onRefresh(); notify(`Idea visibility changed to ${next}.`); } catch (err) { setError(err.message); } finally { setUpdating(''); } };
  return <div className="content-wrap inner-page"><div className="page-kicker"><div className="eyebrow">YOUR WORKSPACE</div><h1>Your ideas, <em>in motion.</em></h1><p>Manage visibility, find guidance, and see what each idea could become.</p></div><div className="page-toolbar"><span>{ideas.length} {ideas.length === 1 ? 'idea' : 'ideas'} shared</span><button className="button button-dark" onClick={onCreate}><Plus size={16} /> Share an idea</button></div>{error && <div className="error-banner">{error}</div>}{loading ? <div className="loading-state"><span className="spinner" /> Loading your ideas…</div> : ideas.length ? <div className="idea-grid">{ideas.map((idea, i) => <article className="owned-idea" key={idea._id || idea.idea_id}><IdeaCard idea={idea} index={i} /><div className="idea-controls"><span className={`visibility-label ${(idea.visibility || 'public').toLowerCase()}`}><ShieldCheck size={13} /> {idea.visibility || 'public'}</span><button className="text-action" onClick={() => setVisibility(idea)} disabled={updating === idea._id}>{updating === idea._id ? 'Saving…' : `Make ${idea.visibility === 'private' ? 'public' : 'private'}`}</button></div></article>)}</div> : <div className="empty-state compact-empty"><div className="empty-art"><Lightbulb size={24} /><span>✳</span></div><div className="eyebrow">YOUR FIRST SPARK</div><h3>You haven’t shared an idea yet.</h3><p>Make your first post and invite others to help shape what comes next.</p><button className="button button-dark" onClick={onCreate}>Share your idea <ArrowRight size={16} /></button></div>}</div>;
}
function Teams({ teams, ideas, progress, feedback, memberships, loading, token, studentId, students, onRefresh, notify }) {
  const [showCreate, setShowCreate] = useState(false);
  const [teamName, setTeamName] = useState('');
  const [ideaId, setIdeaId] = useState('');
  const [description, setDescription] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const ownedIdeas = ideas.filter((idea) => String(idea.student_id) === String(studentId));
  const createTeam = async (event) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const created = await request('/api/teams', { method: 'POST', body: JSON.stringify({ idea_id: ideaId, team_name: teamName, team_description: description }) }, token);
      let ownerAdded = true;
      try { await request('/api/team-members', { method: 'POST', body: JSON.stringify({ team_id: created.team_id, student_id: Number(studentId) }) }, token); }
      catch { ownerAdded = false; }
      setShowCreate(false); setTeamName(''); setDescription(''); onRefresh();
      notify(ownerAdded ? 'Your team is ready to build together.' : 'The team was created, but your membership did not save. Ask a project admin to check the team setup.');
    } catch (err) { setError(err.message); }
    finally { setBusy(false); }
  };
  return <div className="content-wrap inner-page"><div className="page-kicker"><div className="eyebrow">BUILD IT TOGETHER</div><h1>Good ideas need <em>a good team.</em></h1><p>Start a team around one of your ideas and keep the next steps visible.</p></div><div className="page-toolbar"><span>{teams.length} active {teams.length === 1 ? 'team' : 'teams'}</span><button className="button button-dark" onClick={() => setShowCreate(true)} disabled={!ownedIdeas.length}><Plus size={16} /> Start a team</button></div>
    {!ownedIdeas.length && <div className="callout-note"><Lightbulb size={17} /><span>Share an idea first. You can start a team from any idea you own.</span></div>}
    {loading ? <div className="loading-state"><span className="spinner" /> Loading your teams…</div> : teams.length ? <div className="team-grid">{teams.map((team) => { const idea = ideas.find((item) => String(item._id) === String(team.idea_id)); const updates = progress.filter((entry) => Number(entry.team_id) === Number(team.team_id)).sort((a,b) => new Date(b.progress_date) - new Date(a.progress_date)); const latest = updates[0]; return <article className="team-card" key={team.team_id}><div className="team-card-head"><span className="team-icon"><Users size={19} /></span><span className="team-status"><i /> IN PROGRESS</span></div><h2>{team.team_name}</h2><p>{team.team_description || 'A student team working on a shared idea.'}</p><div className="team-idea"><span>BUILDING ON</span><b>{idea?.title || 'InnoBridge idea'}</b></div><div className="progress-meter"><div><span>Latest progress</span><b>{latest ? `${latest.progress_percentage}%` : 'Just getting started'}</b></div><div className="progress-track"><span style={{width:`${latest?.progress_percentage || 0}%`}} /></div></div>{latest && <div className="latest-update"><Clock3 size={14} /><span>{latest.progress_description}</span></div>}<TeamMemberPicker team={team} students={students} memberships={memberships} studentId={studentId} token={token} onAdded={() => { onRefresh(); notify('Teammate added to the project.'); }} />{feedback?.filter((item) => Number(item.team_id) === Number(team.team_id)).map((item) => <div className="mentor-feedback" key={item.feedback_id}><div><span>MENTOR FEEDBACK</span><b>{'★'.repeat(Number(item.rating) || 0)}</b></div><p>{item.comments}</p>{item.suggestions && <small>Next: {item.suggestions}</small>}</div>)}<ProgressForm team={team} token={token} onPosted={() => { onRefresh(); notify('Progress shared with your team.'); }} /></article>; })}</div> : <div className="empty-state compact-empty"><div className="empty-art"><Users size={24} /><span>✳</span></div><div className="eyebrow">BETTER, TOGETHER</div><h3>Your first team starts with an idea.</h3><p>Create a team from one of your own ideas and use progress updates to keep everyone moving.</p><button className="button button-dark" onClick={() => setShowCreate(true)} disabled={!ownedIdeas.length}>Start a team <ArrowRight size={16} /></button></div>}
    {showCreate && <div className="modal-scrim"><div className="idea-modal" role="dialog" aria-modal="true" aria-labelledby="team-modal-title"><div className="modal-head"><div><div className="eyebrow">A SHARED NEXT STEP</div><h2 id="team-modal-title">Start a team</h2><p>Bring collaborators around an idea you own.</p></div><button className="icon-btn" onClick={() => setShowCreate(false)} aria-label="Close"><X size={19} /></button></div><form className="idea-form" onSubmit={createTeam}><label className="field"><span>Choose your idea</span><select value={ideaId} onChange={(e) => setIdeaId(e.target.value)} required><option value="">Select an idea</option>{ownedIdeas.map((idea) => <option key={idea._id} value={idea._id}>{idea.title}</option>)}</select></label><Field label="Team name" value={teamName} onChange={(e) => setTeamName(e.target.value)} required placeholder="Give your team a name" /><label className="field"><span>What will your team work on?</span><textarea value={description} onChange={(e) => setDescription(e.target.value)} rows="3" placeholder="A short note to help your team get started" /></label>{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-actions"><button type="button" className="button button-quiet" onClick={() => setShowCreate(false)}>Cancel</button><button className="button button-dark" disabled={busy}>{busy ? 'Creating…' : 'Create team'} <ArrowRight size={16} /></button></div></form></div></div>}
  </div>;
}
function ProgressForm({ team, token, onPosted }) {
  const [open, setOpen] = useState(false); const [text, setText] = useState(''); const [percent, setPercent] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { await request('/api/progress', { method: 'POST', body: JSON.stringify({ team_id: team.team_id, progress_description: text, progress_percentage: Number(percent) }) }, token); setText(''); setPercent(''); setOpen(false); onPosted(); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  return <div className="progress-action">{!open ? <button className="text-action" onClick={() => setOpen(true)}><TrendingUp size={14} /> Share a progress update</button> : <form onSubmit={submit}><textarea value={text} onChange={(e) => setText(e.target.value)} required rows="2" placeholder="What moved forward?" /><div className="progress-form-row"><input type="number" min="0" max="100" value={percent} onChange={(e) => setPercent(e.target.value)} required placeholder="% complete" /><button className="button button-dark" disabled={busy}>{busy ? 'Saving…' : 'Post update'} <Send size={13} /></button><button className="button button-quiet" type="button" onClick={() => setOpen(false)}>Cancel</button></div>{error && <div className="form-error">{error}</div>}</form>}</div>;
}
function Mentors({ mentors, ideas, requests, token, notify, onRefresh }) {
  const [target, setTarget] = useState(null); const [ideaId, setIdeaId] = useState(''); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const requestGuidance = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { await request('/api/collaboration-requests', { method:'POST', body: JSON.stringify({ idea_id: ideaId, mentor_id: target.mentor_id, request_message: message }) }, token); setTarget(null); setMessage(''); onRefresh(); notify('Your mentorship request has been sent.'); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  return <div className="content-wrap inner-page"><div className="page-kicker"><div className="eyebrow">LEARN FROM THE JOURNEY</div><h1>Good guidance changes <em>everything.</em></h1><p>Meet mentors in the community and ask for guidance on an idea you’re developing.</p></div>{mentors.length ? <div className="mentor-grid">{mentors.map((mentor) => <article className="mentor-card" key={mentor.mentor_id}><span className="mentor-avatar">{initials(`${mentor.first_name || ''} ${mentor.last_name || ''}`)}</span><div className="mentor-info"><h2>{mentor.first_name} {mentor.last_name}</h2><p>{mentor.designation || mentor.expertise || 'InnoBridge mentor'}{mentor.organization ? ` · ${mentor.organization}` : ''}</p></div><div className="mentor-expertise"><span>EXPERTISE</span><b>{Array.isArray(mentor.expertise) ? mentor.expertise.join(' · ') : mentor.expertise || 'General mentorship'}</b></div>{mentor.bio && <p className="mentor-bio">{mentor.bio}</p>}<button className="button button-dark" disabled={!ideas.length} onClick={() => {setTarget(mentor);setIdeaId(ideas[0]?._id || '');setError('');}}>Request guidance <ArrowRight size={15} /></button></article>)}</div> : <div className="empty-state compact-empty"><div className="empty-art"><GraduationCap size={24} /><span>✳</span></div><div className="eyebrow">A GROWING COMMUNITY</div><h3>Mentor profiles will show up here.</h3><p>When mentors join InnoBridge, you can explore their experience and request guidance for your ideas.</p></div>}{!ideas.length && <div className="callout-note"><Lightbulb size={17} /><span>Share an idea you own to request one-on-one guidance.</span></div>}
  {target && <div className="modal-scrim"><div className="idea-modal" role="dialog" aria-modal="true" aria-labelledby="mentor-modal-title"><div className="modal-head"><div><div className="eyebrow">MENTORSHIP REQUEST</div><h2 id="mentor-modal-title">Connect with {target.first_name}</h2><p>Tell them what kind of guidance would help.</p></div><button className="icon-btn" onClick={() => setTarget(null)} aria-label="Close"><X size={19} /></button></div><form className="idea-form" onSubmit={requestGuidance}><label className="field"><span>Choose your idea</span><select value={ideaId} onChange={(e) => setIdeaId(e.target.value)} required>{ideas.map((idea) => <option key={idea._id} value={idea._id}>{idea.title}</option>)}</select></label><label className="field"><span>Your message</span><textarea rows="4" value={message} onChange={(e) => setMessage(e.target.value)} placeholder="What would you like help thinking through?" required /></label>{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-actions"><button type="button" className="button button-quiet" onClick={() => setTarget(null)}>Cancel</button><button className="button button-dark" disabled={busy}>{busy ? 'Sending…' : 'Send request'} <Send size={14} /></button></div></form></div></div>}{requests?.length > 0 && <section className="request-history"><div className="section-heading"><div><div className="eyebrow">YOUR REQUESTS</div><h2>Guidance, <em>in progress.</em></h2></div></div><div className="request-history-list">{[...requests].sort((a,b) => new Date(b.request_date) - new Date(a.request_date)).map((item) => <article key={item.request_id}><span className={`request-status ${(item.request_status || 'pending').toLowerCase()}`}>{item.request_status || 'Pending'}</span><b>{mentors.find((mentor) => Number(mentor.mentor_id) === Number(item.mentor_id))?.first_name || 'Mentor'} · {ideas.find((idea) => String(idea._id) === String(item.idea_id))?.title || 'Your idea'}</b><small>{item.request_message || 'Guidance request sent'} </small></article>)}</div></section>}</div>;
}
function TeamMemberPicker({ team, students, memberships, studentId, token, onAdded }) {
  const [student, setStudent] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const existing = memberships.filter((item) => Number(item.team_id) === Number(team.team_id)).map((item) => Number(item.student_id));
  const available = students.filter((item) => Number(item.student_id) !== Number(studentId) && !existing.includes(Number(item.student_id)));
  const add = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { await request('/api/team-members', {method:'POST', body:JSON.stringify({team_id:team.team_id, student_id:Number(student)})}, token); setStudent(''); onAdded(); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  if (!available.length) return <div className="member-count"><Users size={13} /> {existing.length} {existing.length === 1 ? 'teammate' : 'teammates'} · no more students to add</div>;
  return <form className="member-picker" onSubmit={add}><label><Users size={13} /><select value={student} onChange={(e) => setStudent(e.target.value)} required aria-label="Choose a student to add"><option value="">Add a teammate</option>{available.map((item) => <option key={item.student_id} value={item.student_id}>{item.first_name} {item.last_name} · {item.department || 'Student'}</option>)}</select></label><button className="text-action" disabled={busy}>{busy ? 'Adding…' : 'Add'} <Plus size={13} /></button>{error && <small className="member-error">{error}</small>}</form>;
}
function recommendationItems(data) { if (Array.isArray(data)) return data; return data?.recommendations || data?.results || data?.items || []; }
function Connections({ recommendations, students, teams, myIdeas, token, studentId, onLoad, notify }) {
  const [loaded, setLoaded] = useState(false); const [adding, setAdding] = useState(''); const [error, setError] = useState(''); const [teamByStudent, setTeamByStudent] = useState({});
  useEffect(() => { if (!loaded) { onLoad(); setLoaded(true); } }, [loaded, onLoad]);
  const suggestedPeople = recommendationItems(recommendations.students).map((rec) => { const id = Number(rec.student_id || rec.id); return students.find((item) => Number(item.student_id) === id) || rec; }).filter((item) => Number(item.student_id || item.id) !== Number(studentId));
  const mentorSuggestions = recommendationItems(recommendations.mentors);
  const ownedTeams = teams.filter((team) => myIdeas.some((idea) => String(idea._id) === String(team.idea_id)));
  const add = async (person) => { const key=Number(person.student_id || person.id); const teamId=teamByStudent[key]; if(!teamId){setError('Choose one of your teams first.');return;} setAdding(String(key));setError('');try{await request('/api/team-members',{method:'POST',body:JSON.stringify({team_id:Number(teamId),student_id:key})},token);notify('Teammate added to your team.');}catch(err){setError(err.message);}finally{setAdding('');} };
  return <div className="content-wrap inner-page"><div className="page-kicker"><div className="eyebrow">PEOPLE WHO FIT YOUR WORK</div><h1>Find the right <em>people to build with.</em></h1><p>Recommendations use your interests to help surface potential teammates and mentors.</p></div><section className="recommendation-section"><div className="section-heading"><div><div className="eyebrow">POTENTIAL TEAMMATES</div><h2>Good skills, <em>good chemistry.</em></h2></div></div>{suggestedPeople.length ? <div className="people-grid">{suggestedPeople.map((person) => <article className="person-card" key={person.student_id || person.id}><span className="mentor-avatar">{initials(`${person.first_name || person.name || ''} ${person.last_name || ''}`)}</span><div><h3>{person.first_name ? `${person.first_name} ${person.last_name || ''}` : person.name || 'Student collaborator'}</h3><p>{person.department || person.year ? `${person.department || 'Student'}${person.year ? ` · Year ${person.year}` : ''}` : 'Student community member'}</p></div><div className="tag-row">{(Array.isArray(person.skills) ? person.skills : []).slice(0,3).map((skill)=><span key={skill}>{skill}</span>)}</div>{ownedTeams.length > 0 && <form onSubmit={(e)=>{e.preventDefault();add(person);}} className="invite-inline"><select aria-label="Choose your team" value={teamByStudent[Number(person.student_id || person.id)] || ''} onChange={(e)=>setTeamByStudent({...teamByStudent,[Number(person.student_id || person.id)]:e.target.value})}><option value="">Choose team</option>{ownedTeams.map((team)=><option key={team.team_id} value={team.team_id}>{team.team_name}</option>)}</select><button className="button button-outline" disabled={adding===String(Number(person.student_id || person.id))}>{adding===String(Number(person.student_id || person.id))?'Adding…':'Add teammate'} <Plus size={13}/></button></form>}</article>)}</div> : <div className="empty-inline"><Users size={20}/><div><b>No teammate recommendations yet</b><p>{recommendationItems(recommendations.students).length === 0 ? 'Connect the recommendation service to see skill-based matches. You can still add collaborators from your team page.' : 'As more students join, matching profiles will show here.'}</p></div></div>}{error && <div className="form-error">{error}</div>}</section><section className="recommendation-section"><div className="section-heading"><div><div className="eyebrow">MENTOR MATCHES</div><h2>Advice that fits <em>your next step.</em></h2></div></div>{mentorSuggestions.length ? <div className="people-grid">{mentorSuggestions.map((rec,i)=><article className="person-card" key={rec.mentor_id || rec.id || i}><span className="mentor-avatar"><GraduationCap size={18}/></span><div><h3>{rec.first_name ? `${rec.first_name} ${rec.last_name || ''}` : rec.name || 'Recommended mentor'}</h3><p>{rec.expertise || rec.designation || 'InnoBridge mentor'}</p></div><p className="mentor-bio">{rec.reason || rec.bio || 'A mentor matched to your project interests.'}</p></article>)}</div> : <div className="empty-inline"><GraduationCap size={20}/><div><b>Personalized mentor matches are not available yet</b><p>The recommendation service may be offline. You can browse available mentors directly.</p></div></div>}</section></div>;
}
function MentorDashboard({ requests, ideas, students, token, onRefresh, notify }) {
  const [busyId,setBusyId]=useState(''); const [error,setError]=useState('');
  const handle = async (item, action) => { setBusyId(`${item.request_id}-${action}`);setError('');try{await request(`/api/mentor/guidance-requests/${item.request_id}/${action}`,{method:'POST'},token);onRefresh();notify(action==='accept'?'Guidance request accepted.':'Guidance request declined.');}catch(err){setError(err.message);}finally{setBusyId('');} };
  const pending=requests.filter((item)=>(item.request_status||'Pending').toLowerCase()==='pending');
  return <div className="content-wrap inner-page"><div className="page-kicker"><div className="eyebrow">MENTOR WORKSPACE</div><h1>Help a good idea <em>take its next step.</em></h1><p>Review student requests, respond to projects, and share practical guidance.</p></div><div className="metric-row mentor-metrics"><Metric icon={MessageCircle} label="Pending requests" value={pending.length}/><Metric icon={FolderKanban} label="Projects in community" value={new Set(requests.map((item)=>item.idea_id)).size}/><Metric icon={CheckCheck} label="Responses sent" value={requests.length-pending.length} tone="peach"/></div>{error&&<div className="error-banner">{error}</div>}<div className="section-heading"><div><div className="eyebrow">GUIDANCE INBOX</div><h2>Requests from <em>student builders.</em></h2></div><button className="button button-outline" onClick={onRefresh}><RefreshCw size={14}/> Refresh</button></div>{requests.length ? <div className="guidance-list">{[...requests].sort((a,b)=>new Date(b.request_date)-new Date(a.request_date)).map((item)=>{const student=students.find((row)=>Number(row.student_id)===Number(item.student_id));const idea=ideas.find((row)=>String(row._id)===String(item.idea_id));const status=item.request_status||'Pending';return <article className="guidance-card" key={item.request_id}><div className="guidance-card-top"><span className={`request-status ${status.toLowerCase()}`}>{status}</span><small>{item.request_date?new Date(item.request_date).toLocaleDateString():'Recently'}</small></div><h3>{student?`${student.first_name} ${student.last_name}`:'A student'} wants your guidance</h3><div className="guidance-idea"><Lightbulb size={15}/><span>{idea?.title||`Idea ${item.idea_id}`}</span></div><p>{item.request_message||'The student would appreciate your perspective on their idea.'}</p>{status.toLowerCase()==='pending'&&<div className="guidance-actions"><button className="button button-dark" onClick={()=>handle(item,'accept')} disabled={!!busyId}>{busyId===`${item.request_id}-accept`?'Accepting…':'Accept request'} <Check size={14}/></button><button className="button button-outline" onClick={()=>handle(item,'reject')} disabled={!!busyId}>{busyId===`${item.request_id}-reject`?'Declining…':'Decline'}</button></div>}</article>;})}</div>:<div className="empty-state compact-empty"><div className="empty-art"><MessageCircle size={23}/><span>✳</span></div><div className="eyebrow">INBOX IS CLEAR</div><h3>No guidance requests yet.</h3><p>Student requests will appear here with a note about the idea they’re building.</p></div>}</div>;
}
function MentorProjects({ teams, feedback, memberships, students, ideas, token, notify, onRefresh }) {
  const [target,setTarget]=useState(null);const [comments,setComments]=useState('');const [suggestions,setSuggestions]=useState('');const [rating,setRating]=useState('5');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  const submit=async(event)=>{event.preventDefault();setBusy(true);setError('');try{await request('/api/feedback',{method:'POST',body:JSON.stringify({team_id:Number(target.team_id),comments,suggestions,rating:Number(rating)})},token);setTarget(null);setComments('');setSuggestions('');onRefresh();notify('Feedback shared with the project team.');}catch(err){setError(err.message);}finally{setBusy(false);}};
  return <div className="content-wrap inner-page"><div className="page-kicker"><div className="eyebrow">MENTOR WORKSPACE</div><h1>Thoughtful feedback <em>moves work forward.</em></h1><p>Explore student projects and share clear, actionable guidance with their teams.</p></div>{teams.length ? <div className="mentor-project-grid">{teams.map((team)=>{const idea=ideas.find((item)=>String(item._id)===String(team.idea_id));const teamFeedback=feedback.filter((item)=>Number(item.team_id)===Number(team.team_id));return <article className="mentor-project-card" key={team.team_id}><span className="category-pill">{idea?.category||'Student project'}</span><h2>{team.team_name}</h2><p>{team.team_description||'A student team building an idea into a project.'}</p><div className="team-idea"><span>PROJECT IDEA</span><b>{idea?.title||`Idea ${team.idea_id}`}</b></div><div className="team-idea"><span>TEAM MEMBERS</span><b>{memberships.filter((member)=>Number(member.team_id)===Number(team.team_id)).length || 'Community team'}</b></div>{teamFeedback.length>0&&<div className="mentor-feedback"><div><span>YOUR LAST NOTE</span><b>{'★'.repeat(Number(teamFeedback[teamFeedback.length-1].rating)||0)}</b></div><p>{teamFeedback[teamFeedback.length-1].comments}</p></div>}<button className="button button-dark" onClick={()=>{setTarget(team);setError('');}}>Share feedback <ArrowRight size={14}/></button></article>;})}</div>:<div className="empty-state compact-empty"><div className="empty-art"><FolderKanban size={24}/><span>✳</span></div><div className="eyebrow">PROJECTS ARE GROWING</div><h3>No teams are active yet.</h3><p>Once students form teams, you can review their project details and share feedback.</p></div>}
    {target&&<div className="modal-scrim"><div className="idea-modal" role="dialog" aria-modal="true" aria-labelledby="feedback-title"><div className="modal-head"><div><div className="eyebrow">MENTOR FEEDBACK</div><h2 id="feedback-title">Guide {target.team_name}</h2><p>{ideas.find((idea)=>String(idea._id)===String(target.idea_id))?.title||'Student project'}</p></div><button className="icon-btn" onClick={()=>setTarget(null)} aria-label="Close"><X size={19}/></button></div><form className="idea-form" onSubmit={submit}><label className="field"><span>Rating</span><select value={rating} onChange={(e)=>setRating(e.target.value)}>{[5,4,3,2,1].map((n)=><option value={n} key={n}>{n} / 5 stars</option>)}</select></label><label className="field"><span>What’s working?</span><textarea rows="3" required value={comments} onChange={(e)=>setComments(e.target.value)} placeholder="Share a specific observation about the project"/></label><label className="field"><span>Suggested next steps</span><textarea rows="3" value={suggestions} onChange={(e)=>setSuggestions(e.target.value)} placeholder="Offer one or two actionable directions"/></label>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="button button-quiet" onClick={()=>setTarget(null)}>Cancel</button><button className="button button-dark" disabled={busy}>{busy?'Sending…':'Share feedback'} <Send size={14}/></button></div></form></div></div>}
  </div>;
}

function Notifications({ notifications, token, onRefresh, onBack }) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const unread = notifications.filter((item) => !item.is_read);
  const markRead = async (item) => { try { await request(`/api/notifications/${item.notification_id}/read`, {method:'PUT'}, token); onRefresh(); } catch (err) { setError(err.message); } };
  const markAll = async () => { setBusy(true); setError(''); try { await request('/api/notifications/read-all', {method:'PUT'}, token); onRefresh(); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const sorted = [...notifications].sort((a,b) => new Date(b.created_at) - new Date(a.created_at));
  return <div className="content-wrap inner-page"><div className="page-kicker"><div className="eyebrow">STAY IN THE LOOP</div><h1>Your community, <em>in motion.</em></h1><p>Updates about your ideas, teams, and mentorship requests.</p></div>{error && <div className="error-banner">{error}</div>}{notifications.length ? <><div className="page-toolbar"><span>{unread.length ? `${unread.length} unread update${unread.length === 1 ? '' : 's'}` : 'You’re all caught up'}</span><button className="text-action" disabled={!unread.length || busy} onClick={markAll}><CheckCheck size={15} /> {busy ? 'Updating…' : 'Mark all as read'}</button></div><div className="notification-list">{sorted.map((item) => <article className={`notification-item ${item.is_read ? 'read' : 'unread'}`} key={item.notification_id}><span className="notification-icon"><Bell size={16} /></span><div className="notification-copy"><b>{item.title || 'InnoBridge update'}</b><p>{item.message}</p><small>{item.created_at ? new Date(item.created_at).toLocaleString() : 'Recently'}</small></div>{!item.is_read && <button className="text-action" onClick={() => markRead(item)}>Mark read</button>}</article>)}</div></> : <div className="notification-empty"><div className="notification-orbit"><Bell size={26} /><span>✳</span></div><div className="eyebrow">ALL CAUGHT UP</div><h2>Nothing new right now.</h2><p>When someone connects with your work, you’ll see it here.</p><button className="button button-outline" onClick={onBack}>Back to discover <ArrowRight size={15} /></button></div>}</div>;
}

function IdeaModal({ token, onClose, onCreated }) {
  const [form, setForm] = useState({ title: '', description: '', category: '', problemStatement: '', requiredSkills: '', technologyStack: '', expectedOutcome: '', status: 'open' });
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const update = (e) => setForm({ ...form, [e.target.name]: e.target.value });
  const submit = async (e) => {
    e.preventDefault(); setBusy(true); setError('');
    const payload = { ...form, requiredSkills: form.requiredSkills.split(',').map(s => s.trim()).filter(Boolean), technologyStack: form.technologyStack.split(',').map(s => s.trim()).filter(Boolean) };
    try { await request('/api/ideas', { method: 'POST', body: JSON.stringify(payload) }, token); onCreated(); }
    catch (err) { setError(err.message.includes('Failed to fetch') ? 'The server is offline. Save your draft and try again when connected.' : err.message); }
    finally { setBusy(false); }
  };
  return <div className="modal-scrim" role="presentation" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}><div className="idea-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-head"><div><div className="eyebrow">START WITH A SPARK</div><h2 id="modal-title">Share your idea</h2><p>Give the community enough to see where they could help.</p></div><button className="icon-btn" onClick={onClose} aria-label="Close"><X size={19} /></button></div><form onSubmit={submit} className="idea-form"><Field label="Idea title" name="title" value={form.title} onChange={update} required placeholder="A clear name for your idea" /><div className="field-row"><label className="field"><span>Category</span><select name="category" value={form.category} onChange={update} required><option value="">Choose a category</option>{categories.slice(1).map(item => <option key={item}>{item}</option>)}</select></label><Field label="Expected outcome" name="expectedOutcome" value={form.expectedOutcome} onChange={update} required placeholder="What could change?" /></div><label className="field"><span>What’s the idea?</span><textarea name="description" value={form.description} onChange={update} required rows="3" placeholder="Describe your idea in a few sentences…" /></label><label className="field"><span>What problem are you trying to solve?</span><textarea name="problemStatement" value={form.problemStatement} onChange={update} required rows="2" placeholder="Help collaborators understand why this matters…" /></label><div className="field-row"><Field label="Skills you’re looking for" name="requiredSkills" value={form.requiredSkills} onChange={update} required placeholder="Research, design, coding" /><Field label="Tools or technologies" name="technologyStack" value={form.technologyStack} onChange={update} required placeholder="React, Figma, Python" /></div><div className="privacy-choice"><ShieldCheck size={17} /><span><b>Shared with the community</b><small>Your idea will be visible publicly. You can adjust privacy settings later.</small></span><span className="toggle-on"><Check size={13} /></span></div>{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-actions"><button type="button" className="button button-quiet" onClick={onClose}>Cancel</button><button className="button button-dark" disabled={busy}>{busy ? 'Sharing…' : 'Share my idea'} <ArrowRight size={16} /></button></div></form></div></div>;
}

createRoot(document.getElementById('root')).render(<App />);
